<?php require_once __DIR__.'/../config/config.php'; require_once __DIR__.'/../config/auth.php'; require_login(); $page_title='Dokumen IT'; $rows=$pdo->query('SELECT d.*, COUNT(de.ep_id) ep_count FROM dokumen d LEFT JOIN dokumen_ep de ON de.dokumen_id=d.id GROUP BY d.id ORDER BY d.updated_at DESC')->fetchAll(); require __DIR__.'/../partials/header.php'; ?><div class="d-flex justify-content-between mb-3"><div><h2>Dokumen IT</h2><div class="text-muted">Regulasi, pedoman, SOP, SK, laporan dan dokumen pendukung.</div></div><a class="btn btn-success" href="upload.php">Tambah Dokumen</a></div><div class="card shadow-sm border-0"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Nama</th><th>Kategori</th><th>Versi</th><th>Status</th><th>Review</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['nama'])?></td><td><?=htmlspecialchars($r['kategori'])?></td><td><?=htmlspecialchars($r['versi'])?></td><td><?=htmlspecialchars($r['status'])?></td><td><?=htmlspecialchars($r['tanggal_review']??'-')?></td><td><a class="btn btn-sm btn-outline-success" href="view.php?id=<?=$r['id']?>">Lihat</a></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/../partials/footer.php';